const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Customer_ID",
  "Customer_Name",
  "Region",
  "Total_Spend",
  "Total_Orders",
  "Last_Purchase_Days",
  "Average_Order_Value"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const totalSpend = Number(data.Total_Spend);
  const totalOrders = Number(data.Total_Orders);
  const lastPurchaseDays = Number(data.Last_Purchase_Days);
  const averageOrderValue = Number(data.Average_Order_Value);

  if (
    missingFields.length === 0 &&
    !isNaN(totalSpend) &&
    !isNaN(totalOrders) &&
    !isNaN(lastPurchaseDays) &&
    !isNaN(averageOrderValue) &&
    totalSpend >= 0 &&
    totalOrders >= 0 &&
    lastPurchaseDays >= 0
  ) {

    validItems.push({
      ...data,
      Total_Spend: totalSpend,
      Total_Orders: totalOrders,
      Last_Purchase_Days: lastPurchaseDays,
      Average_Order_Value: averageOrderValue
    });

  } else {

    invalidItems.push({
      customer_id: data.Customer_ID || "Unknown",
      missing_fields: missingFields
    });

  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_records: items.length,
      valid_records: validItems.length,
      invalid_records: invalidItems.length,
      invalid_details: invalidItems,
      customer_data: validItems
    }
  }
];

const data = $json.customer_data;

if (data.length === 0) {
  throw new Error("No customer records found.");
}

const totalCustomers = data.length;

const totalRevenue = data.reduce(
  (sum, customer) =>
    sum + Number(customer.Total_Spend),
  0
);

const averageCustomerSpend =
  totalRevenue / totalCustomers;

const averageOrders =
  data.reduce(
    (sum, customer) =>
      sum + Number(customer.Total_Orders),
    0
  ) / totalCustomers;

const averageOrderValue =
  data.reduce(
    (sum, customer) =>
      sum + Number(customer.Average_Order_Value),
    0
  ) / totalCustomers;

return [
  {
    json: {
      customer_data: data,

      total_customers:
        totalCustomers,

      total_customer_spend:
        Number(totalRevenue.toFixed(2)),

      average_customer_spend:
        Number(averageCustomerSpend.toFixed(2)),

      average_orders:
        Number(averageOrders.toFixed(2)),

      average_order_value:
        Number(averageOrderValue.toFixed(2))
    }
  }
];

const data = $json.customer_data;

const segmentedCustomers = [];

for (const customer of data) {

  const spend = Number(customer.Total_Spend);
  const orders = Number(customer.Total_Orders);
  const daysSincePurchase =
    Number(customer.Last_Purchase_Days);

  let segment;
  let reason;

  if (spend >= 150000 && orders >= 15) {

    segment = "VIP";
    reason =
      "High customer spending combined with frequent purchases.";

  } 
  else if (spend >= 75000 && orders >= 8) {

    segment = "LOYAL";
    reason =
      "Strong spending and consistent purchase activity.";

  } 
  else if (daysSincePurchase > 45) {

    segment = "AT RISK";
    reason =
      "Customer has not made a purchase recently.";

  } 
  else if (spend >= 30000 || orders >= 5) {

    segment = "POTENTIAL";
    reason =
      "Customer shows meaningful spending or purchase activity.";

  } 
  else {

    segment = "LOW VALUE";
    reason =
      "Customer currently has relatively low spending and purchase activity.";

  }

  segmentedCustomers.push({
    ...customer,
    Customer_Segment: segment,
    Segment_Reason: reason
  });
}

const segmentCounts = {
  VIP: 0,
  LOYAL: 0,
  POTENTIAL: 0,
  "AT RISK": 0,
  "LOW VALUE": 0
};

for (const customer of segmentedCustomers) {
  segmentCounts[customer.Customer_Segment]++;
}

return [
  {
    json: {
      ...$json,
      segmented_customers: segmentedCustomers,
      segment_counts: segmentCounts
    }
  }
];

const analysisMap = {};

for (const segment of $json.segment_analysis || []) {
  analysisMap[segment.segment] = segment;
}

return $json.segmented_customers.map(customer => {

  const segmentAnalysis =
    analysisMap[customer.Customer_Segment];

  return {
    json: {

      Customer_ID:
        customer.Customer_ID,

      Customer_Name:
        customer.Customer_Name,

      Region:
        customer.Region,

      Total_Spend:
        customer.Total_Spend,

      Total_Orders:
        customer.Total_Orders,

      Last_Purchase_Days:
        customer.Last_Purchase_Days,

      Average_Order_Value:
        customer.Average_Order_Value,

      Customer_Segment:
        customer.Customer_Segment,

      Segment_Reason:
        customer.Segment_Reason,

      Recommended_Action:
        segmentAnalysis
          ? segmentAnalysis.recommended_action
          : "Continue monitoring customer activity.",

      Created_At:
        new Date().toISOString()
    }
  };
});

